#!/usr/bin/env python3
r"""
Acme Arsenal - Dev Content Restore (PAL, SLES-54931)
Patches GAMEDATA\BOOT\HUB.XML inside MAIN.PAK on a COPY of your ISO:
  * Test Level: points it at WORLD\TEST.KBR (shipped) instead of TEST.KTR (not shipped),
    and borrows L1A1's sky because TEST_SKY.KBW is missing.
MAIN.PAK keeps its exact size; the edited file goes into unused space after its file table.
(The Character Previewer needs no ISO patch - use the .pnach.)

Usage:
  python acme_dev_restore.py "path\to\Looney Tunes - Acme Arsenal (Europe).iso"
      -> writes "<name> [Dev Restore].iso" next to it (your original is not touched)
  python acme_dev_restore.py --in-place game.iso     patch that file directly
  python acme_dev_restore.py --revert game.iso       undo the patch
"""
import sys, os, json, shutil, struct, hashlib

PATCH = json.loads('{"pak_size": 44435243, "pak_sha1": "ee8a320ab9f5d776ad619ae41d9fb08fa388f7d4", "edits": [{"offset": 751616, "original": "", "new": ""}, {"offset": 207, "original": "95020000c606000097010000", "new": "c2060000000000006f010000"}]}')
SECTOR = 2048

def find_file(f, name):
    f.seek(16*SECTOR); pvd = f.read(SECTOR)
    if pvd[1:6] != b"CD001": sys.exit("Not an ISO9660 image.")
    root = pvd[156:156+34]
    lba, size = struct.unpack_from("<I", root, 2)[0], struct.unpack_from("<I", root, 10)[0]
    f.seek(lba*SECTOR); d = f.read(size); i = 0
    while i < len(d):
        ln = d[i]
        if ln == 0:
            i = (i//SECTOR + 1)*SECTOR; continue
        nl = d[i+32]; nm = d[i+33:i+33+nl].decode("latin1").split(";")[0].upper()
        if nm == name:
            return struct.unpack_from("<I", d, i+2)[0]*SECTOR, struct.unpack_from("<I", d, i+10)[0]
        i += ln
    sys.exit(f"{name} not found in the ISO root.")

def main():
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    flags = {a for a in sys.argv[1:] if a.startswith("--")}
    if len(args) != 1: print(__doc__); sys.exit(1)
    iso = args[0]
    if not os.path.isfile(iso): sys.exit(f"Can't find {iso}")
    revert = "--revert" in flags
    target = iso
    with open(iso, "rb") as f:   # validate before copying anything
        base, size = find_file(f, "MAIN.PAK")
        if size != PATCH["pak_size"]: sys.exit("MAIN.PAK size doesn't match - is this the PAL SLES-54931 disc?")
    if not revert and "--in-place" not in flags:
        root, ext = os.path.splitext(iso)
        target = root + " [Dev Restore]" + (ext or ".iso")
        if os.path.exists(target): sys.exit(f"{target} already exists - delete it first.")
        print(f"Copying ISO to:\n  {target}\n(this takes a minute)...")
        shutil.copyfile(iso, target)
    with open(target, "r+b") as f:
        base, size = find_file(f, "MAIN.PAK")
        if size != PATCH["pak_size"]: sys.exit("MAIN.PAK size doesn't match - is this the PAL SLES-54931 disc?")
        want, put = ("new", "original") if revert else ("original", "new")
        # check every region first, so we never half-patch
        state = set()
        for e in PATCH["edits"]:
            f.seek(base + e["offset"]); cur = f.read(len(e["original"])//2).hex()
            state.add("original" if cur == e["original"] else "new" if cur == e["new"] else "other")
        if state == {put}: print("Already " + ("reverted." if revert else "patched.")); return
        if state != {want}: sys.exit("MAIN.PAK doesn't match the expected version; nothing was changed.")
        for e in PATCH["edits"]:
            f.seek(base + e["offset"]); f.write(bytes.fromhex(e[put]))
    print("Reverted." if revert else "Done! Load the [Dev Restore] ISO in PCSX2 with the 'Boot: Development' patch and pick Test Level.")

if __name__ == "__main__":
    main()
